from datetime import datetime

def parse_booking(text):
    # text looks like "25/12/2026 18:05"
    return datetime.strptime(text, "%d/%m/%Y %H:%M")

print(parse_booking("25/12/2026 18:05"))

from datetime import datetime, timedelta, timezone

IST = timezone(timedelta(hours=5, minutes=30), "IST")

def ist_display(utc_text):
    moment = datetime.fromisoformat(utc_text)
    return moment.astimezone(IST).strftime("%d %b %Y, %I:%M %p %Z")

print(ist_display("2026-10-18T22:15:00+00:00"))

